import importlib.util, random, struct, sys

def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m

old = load("/tmp/oldver/dns_old.py", "dns_old")
new = load("/home/c/brix5/a/task078/dns.py", "dns_new")
rng = random.Random(424242)

def wname(name):
    return b"".join(bytes([len(l)]) + l.encode() for l in name.rstrip(".").split(".")) + b"\x00"

origin = "example."
soa = wname("ns."+origin)+wname("admin."+origin)+struct.pack(">IIIII",1,7200,3600,1209600,60)
zone = {"origin":origin,"records":[
 {"name":origin,"type":6,"class":1,"ttl":100,"rdata":soa},
 {"name":"ns."+origin,"type":1,"class":1,"ttl":100,"rdata":b"\x0a\x00\x00\x01"},
 {"name":"www."+origin,"type":1,"class":1,"ttl":100,"rdata":b"\x0a\x00\x00\x02"}]}
plan = [("u1", [])]
Ro = old.Resolver(zone, plan, timeout=5)
Rn = new.Resolver(zone, plan, timeout=5)

def pq(nm, qt, qid=1, flags=0x0100):
    return struct.pack(">HHHHHH",qid,flags,1,0,0,0)+wname(nm)+struct.pack(">HH",qt,1)

names = ["ns.example.","www.example.","missing.example.","nodata.example."]
fails=[]; N=0
now=0
for i in range(300):
    now += rng.randint(0,30)
    nm=rng.choice(names); qt=rng.choice([1,28,15]); lim=rng.choice([12,100,512,4096])
    q=pq(nm,qt,rng.randrange(65536))
    def run(R):
        try: return ("ok", R.resolve(q, now, lim))
        except Exception as e: return ("err", type(e).__name__)
    a=run(Ro); b=run(Rn); N+=1
    if a!=b: fails.append(("resolve",i,a,b))
    if Ro.stats()!=Rn.stats(): fails.append(("stats",i))
    if Ro.cache_stats(now)!=Rn.cache_stats(now): fails.append(("cstats",i))

# zone snapshot / state round-trips
for now2 in (0, now):
    try:
        so_=Ro.dump_state(now2); sn_=Rn.dump_state(now2)
        if so_!=sn_: fails.append(("dump_state",now2))
    except Exception as e:
        fails.append(("dump_state_exc",now2,type(e).__name__))
try:
    text = Rn.dump_state(now)
    Rn2 = new.load_state(text, plan, now, timeout=5)
    Ro2 = old.load_state(text, plan, now, timeout=5)
    if Rn2.stats()!=Ro2.stats(): fails.append(("load_state stats",))
    if Rn2.cache_stats(now)!=Ro2.cache_stats(now): fails.append(("load_state cstats",))
except Exception as e:
    fails.append(("load_state_exc", type(e).__name__, str(e)))

# reload_zone keeps working (fresh cache anyway)
try:
    r1=Ro.reload_zone(zone); r2=Rn.reload_zone(zone)
    if r1!=r2: fails.append(("reload_zone",r1,r2))
except Exception as e:
    fails.append(("reload_zone_exc",type(e).__name__))

print("N=",N,"fails=",fails[:10], "total", len(fails))
sys.exit(1 if fails else 0)

